mapper.select:
SELECT 

ORDER BY COALESCE(d.date,DATE(a.taken_at),DATE(a.created_at)) DESC, dm.sort ASC, a.asset_id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.delete:
DELETE fm FROM favorite_media fm
INNER JOIN media_asset a ON a.asset_id = fm.asset_id
WHERE fm.user_id = #{userId} AND a.public_id = #{assetId}
